-- Initial BandUp schema: PostgreSQL 16 / Prisma 6.19.0.
-- IDs generated by Postgres; Prisma client also reads these defaults.

CREATE TYPE "TestType" AS ENUM ('PLACEMENT', 'READING', 'LISTENING', 'WRITING', 'SPEAKING', 'VOCABULARY');
CREATE TYPE "TestStatus" AS ENUM ('DRAFT', 'PUBLISHED', 'ARCHIVED');
CREATE TYPE "QuestionType" AS ENUM ('MULTIPLE_CHOICE', 'TRUE_FALSE', 'FILL_IN_BLANK', 'SHORT_ANSWER', 'ESSAY', 'AUDIO_RESPONSE');
CREATE TYPE "SubmissionStatus" AS ENUM ('IN_PROGRESS', 'SUBMITTED', 'GRADED');

CREATE TABLE "users" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "email" VARCHAR(320) NOT NULL,
    "password_hash" TEXT,
    "full_name" VARCHAR(150) NOT NULL,
    "avatar_url" TEXT,
    "current_band" DECIMAL(3,1),
    "target_band" DECIMAL(3,1),
    "expected_exam_date" DATE,
    "daily_study_minutes" INTEGER,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "users_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "users_current_band_range" CHECK ("current_band" IS NULL OR "current_band" BETWEEN 0 AND 9),
    CONSTRAINT "users_target_band_range" CHECK ("target_band" IS NULL OR "target_band" BETWEEN 0 AND 9),
    CONSTRAINT "users_daily_study_minutes_positive" CHECK ("daily_study_minutes" IS NULL OR "daily_study_minutes" BETWEEN 1 AND 1440)
);

CREATE TABLE "tests" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "title" VARCHAR(255) NOT NULL,
    "description" TEXT,
    "type" "TestType" NOT NULL,
    "status" "TestStatus" NOT NULL DEFAULT 'DRAFT',
    "duration_minutes" INTEGER,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "tests_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "tests_duration_positive" CHECK ("duration_minutes" IS NULL OR "duration_minutes" > 0)
);

CREATE TABLE "questions" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "test_id" UUID NOT NULL,
    "position" INTEGER NOT NULL,
    "type" "QuestionType" NOT NULL,
    "prompt" TEXT NOT NULL,
    "options" JSONB,
    "answer_key" JSONB,
    "explanation" TEXT,
    "points" INTEGER NOT NULL DEFAULT 1,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "questions_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "questions_position_positive" CHECK ("position" > 0),
    CONSTRAINT "questions_points_nonnegative" CHECK ("points" >= 0)
);

CREATE TABLE "submissions" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "user_id" UUID NOT NULL,
    "test_id" UUID NOT NULL,
    "status" "SubmissionStatus" NOT NULL DEFAULT 'IN_PROGRESS',
    "answers" JSONB NOT NULL,
    "score" DECIMAL(8,2),
    "max_score" DECIMAL(8,2),
    "band_estimate" DECIMAL(3,1),
    "feedback" JSONB,
    "started_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "submitted_at" TIMESTAMP(3),
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "submissions_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "submissions_score_nonnegative" CHECK ("score" IS NULL OR "score" >= 0),
    CONSTRAINT "submissions_max_score_nonnegative" CHECK ("max_score" IS NULL OR "max_score" >= 0),
    CONSTRAINT "submissions_band_range" CHECK ("band_estimate" IS NULL OR "band_estimate" BETWEEN 0 AND 9)
);

CREATE TABLE "vocabularies" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "user_id" UUID NOT NULL,
    "word" VARCHAR(128) NOT NULL,
    "meaning" TEXT NOT NULL,
    "phonetic" VARCHAR(128),
    "part_of_speech" VARCHAR(64),
    "example_sentence" TEXT,
    "is_learned" BOOLEAN NOT NULL DEFAULT false,
    "review_count" INTEGER NOT NULL DEFAULT 0,
    "last_reviewed_at" TIMESTAMP(3),
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "vocabularies_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "vocabularies_review_count_nonnegative" CHECK ("review_count" >= 0)
);

CREATE UNIQUE INDEX "users_email_key" ON "users"("email");
CREATE INDEX "tests_type_status_idx" ON "tests"("type", "status");
CREATE UNIQUE INDEX "questions_test_id_position_key" ON "questions"("test_id", "position");
CREATE INDEX "submissions_user_id_created_at_idx" ON "submissions"("user_id", "created_at");
CREATE INDEX "submissions_test_id_idx" ON "submissions"("test_id");
CREATE UNIQUE INDEX "vocabularies_user_id_word_key" ON "vocabularies"("user_id", "word");
CREATE INDEX "vocabularies_user_id_created_at_idx" ON "vocabularies"("user_id", "created_at");

ALTER TABLE "questions"
    ADD CONSTRAINT "questions_test_id_fkey"
    FOREIGN KEY ("test_id") REFERENCES "tests"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "submissions"
    ADD CONSTRAINT "submissions_user_id_fkey"
    FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "submissions"
    ADD CONSTRAINT "submissions_test_id_fkey"
    FOREIGN KEY ("test_id") REFERENCES "tests"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "vocabularies"
    ADD CONSTRAINT "vocabularies_user_id_fkey"
    FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
